entries[183378] = { ["name"] = "Erinnerung an den Springer", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\nGegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\n\nSpringer Runenschnitzmacht\n'Heldenhafter Sprung' erhält 2 zusätzliche Aufladungen.\nRunenschnitzen: Taille, Füße\nQuelle: Gegen Ehre von Lieferant Zo'kuul erhältlich. Runenschnitzen muss freigeschaltet sein, um diese Erinnerung kaufen zu können.\nBenötigt: Krieger" }
entries[183379] = { ["name"] = "Erinnerung an den verformten Spiegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nVerformter Spiegel Runenschnitzmacht\n'Zauberreflexion' hält 60% länger an und wirkt sich auf Euren nächsten Verbündeten aus. (1s Abklingzeit)\nRunenschnitzen: Hals, Brust\nQuelle: Quest: Die Große Schatzkammer\nBenötigt: Krieger" }
entries[183380] = { ["name"] = "Erinnerung an einen seismischen Nachhall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSeismischer Nachhall Runenschnitzmacht\nFuror\nWenn 'Wirbelwind' 3 oder mehr Gegner trifft, werden sie noch 1 weiteres Mal getroffen und erleiden dabei 100% des Schadens.\n\nWaffen\nWenn 'Wirbelwind' 3 oder mehr Gegner trifft, werden sie noch 1 weiteres Mal getroffen und erleiden dabei 80% des Schadens.\n\nSchutz\nWenn 'Wirbelwind' oder 'Rache' 3 oder mehr Gegner trifft, werden sie noch 1 weiteres Mal getroffen und erleiden dabei 75% des Schadens.\nRunenschnitzen: Kopf, Schulter, Füße\nQuelle: Dungeonbeute: Halkias, der Sündenbefleckte Goliath\nBenötigt: Krieger" }
entries[183381] = { ["name"] = "Erinnerung an die gequälten Könige", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSignet der Gequälten Könige Runenschnitzmacht\nDas Aktivieren von 'Klingensturm', 'Tollkühnheit' oder 'Avatar' setzt zufällig eine der beiden anderen Fähigkeiten mit verringerter Effektivität ein.\nRunenschnitzen: Handgelenk, Finger\nQuelle: Schlachtzugbeute: Generäle der Steinlegion\nBenötigt: Krieger" }
entries[183382] = { ["name"] = "Erinnerung an einen Schlachtenfürsten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nSchlachtenfürst Runenschnitzmacht\n'Überwältigen' hat eine Chance von 40%, die Abklingzeit von 'Tödlicher Stoß' abzuschließen und die Wutkosten Eures nächsten Einsatzes von 'Tödlicher Stoß' um 15 zu verringern. (Procchance: 40%, 100ms Abklingzeit)\nRunenschnitzen: Hals, Handgelenk\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Seelenschmieden, Ebene 3+\nBenötigt: Krieger (Waffen)" }
entries[183383] = { ["name"] = "Erinnerung an einen ausdauernden Schlag", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nAusdauernder Schlag Runenschnitzmacht\nEure Fähigkeit 'Tödlicher Stoß' hat eine Chance von 25%, Euer Ziel 6 Sek. lang mit dem Effekt von 'Kolossales Schmettern' zu belegen. (Procchance: 25%)\nRunenschnitzen: Kopf, Taille\nQuelle: Beute von: Torghast, Turm der Verdammten. Skoldushalle, Ebene 3+\nBenötigt: Krieger (Waffen)" }
entries[183384] = { ["name"] = "Erinnerung an den Ausbeuter", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nAusbeuter Runenschnitzmacht\n'Hinrichten' lässt das Ziel durch Euren nächsten Einsatz von 'Tödlicher Stoß' 50% mehr Schaden erleiden. Bis zu 2-mal stapelbar.\nRunenschnitzen: Schulter, Finger\nQuelle: Schlachtzugbeute: Graf Denathrius\nBenötigt: Krieger (Waffen)" }
entries[183385] = { ["name"] = "Erinnerung an die verlorene Kontrolle", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nAußer Kontrolle Runenschnitzmacht\nWährend 'Klingensturm' aktiv ist, setzt Ihr automatisch insgesamt 2-mal 'Tödlicher Stoß' gegen zufällige Gegner in der Nähe ein.\nRunenschnitzen: Handgelenk, Hände, Finger\nQuelle: Dungeonbeute: Xav der Unbesiegte\nBenötigt: Krieger (Waffen)" }
entries[183386] = { ["name"] = "Erinnerung an Fujieda", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nKadenz von Fujieda Runenschnitzmacht\n'Blutdurst' erhöht Euer Tempo für 12 Sek. um 1%. Bis zu 5-mal stapelbar. (500ms Abklingzeit)\nRunenschnitzen: Taille, Beine\nQuelle: Weltbossbeute: Mortanis\nBenötigt: Krieger (Furor)" }
