entries[183388] = { ["name"] = "Erinnerung an eine waghalsige Verteidigung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nWaghalsige Verteidigung Runenschnitzmacht\nTreffer mit 'Toben' haben eine Chance von 20%, die verbleibende Abklingzeit von 'Tollkühnheit' und 'Wütende Regeneration' um 1 Sek. zu verringern.\nRunenschnitzen: Kopf, Taille, Hände\nQuelle: Beute von: Torghast, Turm der Verdammten. Mort'regar, Ebene 3+\nBenötigt: Krieger (Furor)" }
entries[183389] = { ["name"] = "Erinnerung an den Willen des Berserkers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nWille des Berserkers Runenschnitzmacht\nSobald 'Tollkühnheit' endet, wird Euer kritischer Trefferwert für 12 Sek. um 7% erhöht. Eure Fähigkeit 'Wütender Schlag' setzt die Dauer dieses Effekts zurück.\nRunenschnitzen: Brust, Rücken\nQuelle: Schlachtzugbeute: Schlickfaust\nBenötigt: Krieger (Furor)" }
entries[183390] = { ["name"] = "Erinnerung an eine Revanche", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nRevanche Runenschnitzmacht\n'Sturmangriff' und 'Einschreiten' gewähren Euch 'Schildblock' für 4 Sek. sowie 'Rache!' und erzeugen 20 Wut. (100ms Abklingzeit)\nRunenschnitzen: Beine, Füße\nQuelle: Beute von: Torghast, Turm der Verdammten. Die Oberen Ebenen, Ebene 3+\nBenötigt: Krieger (Schutz)" }
entries[183391] = { ["name"] = "Erinnerung an den Wall", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nDer Wall Runenschnitzmacht\n'Schildschlag' erzeugt 5 zusätzliche Wut und verringert die verbleibende Abklingzeit von 'Schildwall' um 5 Sek.\nRunenschnitzen: Schulter, Rücken\nQuelle: Schlachtzugbeute: Hungernder Zerstörer\nBenötigt: Krieger (Schutz)" }
entries[183392] = { ["name"] = "Erinnerung an den Donnerfürst", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nBenutzen: Stellt die folgende Erinnerung des Runenmetzes wieder her:\n\nDonnerfürst Runenschnitzmacht\nFür jeden von 'Donnerknall' getroffenen Gegner wird die verbleibende Abklingzeit von 'Demoralisierender Ruf' um 1.5 Sek. verringert, bis maximal 4.5 Sek.\nRunenschnitzen: Füße, Hände\nQuelle: Dungeonbeute: Oryphrion\nBenötigt: Krieger (Schutz)" }
