entries[183517] = { ["name"] = "Seite 76 des Necro-mjam-nicon", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Füttert dem Necro-mjam-nicon die Seite 76, um einen zusätzlichen Effekt zu erhalten.\n\"Die Seite ist zerrissen und alt. Vielleicht wäre dies eine willkommene Ergänzung für das Necro-mjam-nicon.\"" }
entries[183518] = { ["name"] = "Hofsündenmähren", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Hof der Ernter\n- Ehrfürchtig\n\n\"Sündenmähren waren einst die Rosse dunkler Seelen und gelangten im Sog ihrer eigenen Sünden oder der Sünden ihrer Gebieter nach Revendreth. Obwohl sich manche von ihnen für die Freiheit entschieden haben, dienen viele von ihnen im Tode der Finsternis genau so weiter, wie sie es auch zu Lebzeiten getan haben.\"\nVerkäufer:\nHerrin Mihaela\nZone:\nRevendreth\nFraktion:\nHof der Ernter - Ehrfürchtig\nKosten:\n30." }
