entries[183520] = { ["name"] = "Samen der wilden Nachtblüte", ["text"] = "Konservatorium der Königin\nWird beim Aufheben gebunden\nBenutzen: Erfüllt einen Wildsamen des Nachwachsens mit Samen, um einen neuen Katalysator wachsen zu lassen.\n\"Aus diesen Samen wächst eine magische Blüte, die den Ertrag der Belohnungen, die von einem Geist bei der Wiedergeburt angeboten werden, und die Anzahl an Katalysatoren aus Katalysatorsamen erhöht.\"\nVerkaufspreis:" }
entries[183521] = { ["name"] = "Temporalblättersamen", ["text"] = "Konservatorium der Königin\nWird beim Aufheben gebunden\nBenutzen: Erfüllt einen Wildsamen des Nachwachsens mit Samen, um einen neuen Katalysator wachsen zu lassen.\n\"Aus diesen Samen wachsen verzauberte Blätter, die den Prozess des Wildsamens des Nachwachsens beschleunigen.\"\nVerkaufspreis:" }
entries[183522] = { ["name"] = "Wildsamenwurzelfasersamen", ["text"] = "Konservatorium der Königin\nWird beim Aufheben gebunden\nBenutzen: Erfüllt einen Wildsamen des Nachwachsens mit Samen, um einen neuen Katalysator wachsen zu lassen.\n\"Aus diesen Samen wächst eine besondere Wurzel, die die Qualität der Belohnungen erhöht, die von einem Geist bei der Wiedergeburt angeboten werden.\"\nVerkaufspreis:" }
entries[183523] = { ["name"] = "Miniaturisiertes Phylakterium", ["text"] = "Wird beim Aufheben gebunden\n\"Dieses Phylakterium ist trotz all seiner Bemühungen nur groß genug, um zu zeigen, wo sein Besitzer gestorben ist, und kann seine Seele nicht zurückholen oder schützen.\"" }
