entries[183615] = { ["name"] = "Kriegsflickdüsterhund", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Diese Kriegshunde werden im Haus der Konstrukte erschaffen, um Reiter in das Schlachtgetümmel zu tragen und zugleich gegnerische Reittiere zu zerfetzen.\"\nAbenteuer:\nShadowlands" }
