entries[183714] = { ["name"] = "Sumpfschilf", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen verkümmernden Morastkriecher beschwört.\nBeschwört eine Sternenlaterne, die in den Himmel davonschwebt.\n80 ( 80)" }
entries[183715] = { ["name"] = "Sündensturzgargon", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Ruhmstufe 23\n\n\"Gargons sind die treuen Reittiere und Begleiter der Venthyr. Renathal hat viele von ihnen herrenlos in Sündensturz gefunden, wo sie auf ihre Wiedererweckung und die Zuteilung zu würdigen Mitgliedern des Pakts warten.\"\nPakt:\nVenthyr\nZone:\nRevendreth" }
entries[183716] = { ["name"] = "Venthyrsündenstein", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Bringt Euch zurück nach: Ruhestein-Ort. Sprecht mit einem Gastwirt an einem anderen Ort, um Euren Heimatort zu ändern.\n\nKann nur von denjenigen verwendet werden, die den Venthyr die Treue geschworen haben.\nBenötigt Ruhmstufe 11\n\"Bindet Euch an mehr als ein Gasthaus.\"" }
