entries[183740] = { ["name"] = "Vergoldeter Streuner", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nErfordert einen ehrfürchtigen Ruf bei den Aufgestiegen.\n\n\"Der mächtige Larion ist das Spitzenraubtier der Bastion. Das heißt aber nicht, dass er nicht hin und wieder ein Nickerchen in den sonnendurchfluteten Feldern genießt.\"\nVerkäufer:\nAdjutantin Nikos\nZone:\nBastion\nKosten:" }
entries[183741] = { ["name"] = "Aufgestiegene Himmelsmähne", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Nur diejenigen, die sich gegen die vereinte Macht der Aufgestiegenen behauptet haben, dürfen dieses Reittier ihr Eigen nennen.\"\nSchatz:\nVorrat der Aufgestiegenen\nZone:\nBastion" }
entries[183742] = { ["name"] = "Feindliche Infiltration - Vorwort", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\n\"Ein von unbekannter Hand verfasster Bericht. Die Unterschrift auf der letzten Seite wurde unleserlich gemacht.\"\n<Zum Lesen rechtsklicken>\nVerkaufspreis:" }
