entries[183786] = { ["name"] = "Vogel der Freude", ["text"] = "Monstrositätenflickerei\nWird beim Aufheben gebunden\nEinzigartig\nHandwerksmaterial\n\"Ein kleiner, in einen Käfig eingesperrter Vogel, der zu gerne bei jemandem auf der Schulter sitzen würde.\"\nVerkaufspreis:" }
entries[183787] = { ["name"] = "Stygischer Dämpfer", ["text"] = "Ätherisch\nDer Schlund\nWird beim Aufheben gebunden\nEinzigartig\nDauer: 10 min (Realzeit)\nBenutzen: Beschwört einen stygischen Dämpfer, der den vom vollgefressenen Schemenhund erlittenen Schaden um 20% erhöht und den erlittenen Schaden von allen in seiner Nähe um 20% verringert.\n\nKann im Prodigum und in der Grube der Qualen verwendet werden.\nVerkaufspreis:" }
entries[183789] = { ["name"] = "Sechsmeilenrucksack", ["text"] = "Monstrositätenflickerei\nWird beim Aufheben gebunden\nEinzigartig\nHandwerksmaterial\n\"Ein legendärer Rucksack, der einst einem Venthyr mit beachtlichen Sprungfähigkeiten gehört hat.\"\nVerkaufspreis:" }
entries[183790] = { ["name"] = "Tellermeister Stue", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig (5)\nBenutzen: Ruft Tellermeister Stue zu Eurer Position. (1 Stunde Abklingzeit)\n\"Stue hat immer etwas zu Essen parat.\"\nVerkaufspreis:" }
entries[183791] = { ["name"] = "Stibitzte Materialien", ["text"] = "Questgegenstand\nEinzigartig (8)\n\"Sieht aus, als hätte ein Spriggan daran herumgenagt.\"" }
entries[183792] = { ["name"] = "Werkzeug des Handwerkers", ["text"] = "Questgegenstand\n\"Wird zur Herstellung edler Dinge verwendet, es sei denn, es gelangt in die falschen Hände.\"" }
entries[183793] = { ["name"] = "Himmlische Erfrischung", ["text"] = "Benutzen: Richtet eine himmlische Erfrischung her, die bis zu 35 Mitglieder Eures Schlachtzugs oder Eurer Gruppe sättigen kann!\n\nStellt im Verlauf von 20 Sek. 86538 Gesundheit und 115385 Mana wieder her. Ihr müsst beim Essen sitzen bleiben. (5 Min Abklingzeit)" }
entries[183794] = { ["name"] = "Bauplan: Himmlische Erfrischung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest." }
entries[183795] = { ["name"] = "Benachrichtigung über eine Speziallieferung", ["text"] = "Wird beim Aufheben gebunden\n\"Dieser Brief liest sich so, als hätte der Verfasser unter enormem Zeitdruck gestanden oder wäre sehr zerstreut gewesen... oder vielleicht auch beides.\"\n<Zum Lesen rechtsklicken>" }
entries[183796] = { ["name"] = "Marklarvenfleisch", ["text"] = "Questgegenstand\n\"Riecht so gut, wie es aussieht.\"" }
entries[183797] = { ["name"] = "Verband des Kreuzfahrers", ["text"] = "Questgegenstand\nBenutzen: Heilt die Wunden eines verletzten Verbündeten." }
entries[183798] = { ["name"] = "Silessas Kampfharnisch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man Kampfgargon Silessa als Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Silessa hat bei der großen Invasion des Lichts tapfer an der Seite ihres Meisters gekämpft. Nach dem Kampf wurde ihr von ihrem Meister befohlen, eine sehr wertvolle Schatzkammer zu bewachen.\"\nPakt:\nVenthyr\nZone:\nRevendreth" }
entries[183799] = { ["name"] = "Veränderlicher Katalysator", ["text"] = "Ätherisch\nDer Schlund\nWird beim Aufheben gebunden\nEinzigartig\nDauer: 10 min (Realzeit)\nBenutzen: Platziert einen veränderlichen Katalysator, der bei Benutzung die Fähigkeit gewährt, sich mit 'Essenzverschiebung' über das Schlachtfeld zu bewegen.\n\nKann auf den Seelenbefleckten Feldern oder im Schlupfloch des Folterers im Schlund verwendet werden.\n60 ( 60)\nVerkaufspreis:" }
entries[183800] = { ["name"] = "Bernsteinardenmotte", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\n\n\"Das leuchtende Orange der Bernsteinardenmotte signalisiert Raubtieren, dass es gefährlich wäre, sie zu verspeisen. Eine dieser Kreaturen zu verzehren, würde ein Raubtier für mehrere Jahre in einen traumlosen Schlaf versetzen.\"\nBeute:\nVorräte der Wilden Jagd\nZone:\nArdenwald" }
entries[183801] = { ["name"] = "Schillernder Schwirrling", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nBenötigt Marasmius\n- Respektvoll\n\n\"Diese minzgrünen Motten sind sehr freundlich. Sie mögen es besonders, wenn man ihnen den Kopfflaum kräftig durchbürstet. Außerdem mögen sie Musik und Poesie.\"\nVerkäufer:\nCortinarius\nZone:\nArdenwald" }
entries[183802] = { ["name"] = "Erinnerung an die Verschmähten", ["text"] = "Questgegenstand\n\"Ein kleiner Bruchteil von Lysonias Erinnerungen an ihre Zeit unter den Verschmähten.\"" }
entries[183803] = { ["name"] = "Schlüsselsteinaffix hinzufügen: Stolz", ["text"] = "Dauer: 12 std. (Realzeit)\nBenutzen: Fügt einem mythischen Schlüsselstein das Affix Stolz hinzu.\nVerkaufspreis:" }
entries[183804] = { ["name"] = "Großer Glücksbringer", ["text"] = "Wird beim Aufheben gebunden\n\"Wie ist er hierhergelangt? Was für ein Glück, dass Ihr ihn gefunden habt.\"\nVerkaufspreis:" }
entries[183805] = { ["name"] = "Ruhiger Geist des Kosmos", ["text"] = "Konservatorium der Königin\nWird beim Aufheben gebunden\nBenutzen: Erfüllt einen Wildsamen des Nachwachsens mit diesem Geist.\n\"Dieser Geist enthält die Essenz eines sehr mächtigen und doch beruhigenden Geistes.\"\nVerkaufspreis:" }
entries[183806] = { ["name"] = "Energischer Geist der Neugier", ["text"] = "Konservatorium der Königin\nWird beim Aufheben gebunden\nBenutzen: Erfüllt einen Wildsamen des Nachwachsens mit diesem Geist.\n\"Dieser Geist enthält die Essenz eines sehr mächtigen und neugierigen Geistes.\"\nVerkaufspreis:" }
entries[183807] = { ["name"] = "Stygischer Zwang", ["text"] = "Ätherisch\nDer Schlund\nWird beim Aufheben gebunden\nEinzigartig\nDauer: 10 min (Realzeit)\nBenutzen: Zwingt bestimmte Todeselementare dazu, als Transportmittel innerhalb des Bestienlabyrinths zu dienen.\n\nKann im Bestienlabyrinth im Schlund verwendet werden.\n60 ( 60)\nVerkaufspreis:" }
entries[183808] = { ["name"] = "Angebundenes Konstrukt", ["text"] = "Benutzen: Wirft den Kopf einem freundlich gesinnten Spielercharakter zu. Falls er Platz in seinem Rucksack hat, wird er ihn fangen!\n\"Haltet die Leine gut fest!\"\nVerkaufspreis:" }
entries[183809] = { ["name"] = "Markgraf Krexus' Tribut", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Erschafft ein Hologramm von König Mechagon. (1 Stunde Abklingzeit)\nVerkaufspreis:" }
entries[183810] = { ["name"] = "Schattenlandemini: Großmeister Vole", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört den Sockel und stellt eine Figur aus Eurer Sammlung aus. (3 Min Abklingzeit)\n\"Eine Sammelfigur des größten Champions, der jemals im Theater der Schmerzen gekämpft hat.\"\nVerkaufspreis:" }
entries[183811] = { ["name"] = "Bester Freund des Konstrukts", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Beschwört Naht, damit er Euch 2 Min. lang im Kampf unterstützt. Kann nur im Freien in den Schattenlanden verwendet werden. (10 Min Abklingzeit)\n60 ( 60)\n\"Alle guten Hunde kommen nach Maldraxxus.\"\nVerkaufspreis:" }
entries[183821] = { ["name"] = "Remornia", ["text"] = "Questgegenstand\n\"In dieser belebten Klinge schreit eine dunkle Präsenz danach, entfesselt zu werden.\"" }
entries[183822] = { ["name"] = "Überlebensausrüstung für Eiskrone", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Öffnet den Beutel.\n\"Grundversorgungspaket für neue Rekruten. Enthält Gold, Tränke und Rationen.\"\nVerkaufspreis:" }
entries[183823] = { ["name"] = "Trank des ungehinderten Übertritts", ["text"] = "Benutzen: Macht Euch 5 Sek. lang immun gegen Betäubungseffekte und bewegungseinschränkende Effekte. Bereits bestehende Effekte dieser Art werden nicht entfernt. (5 Min Abklingzeit)\nVerkaufspreis:" }
entries[183824] = { ["name"] = "Truhe voller Ersatzwaffen", ["text"] = "Monstrositätenflickerei\nWird beim Aufheben gebunden\nEinzigartig\nHandwerksmaterial\n\"Eine Sammlung einzigartiger Waffen, die womöglich von Konstrukten verwendet werden können.\"\nVerkaufspreis:" }
entries[183825] = { ["name"] = "Überdimensioniertes Monokel", ["text"] = "Monstrositätenflickerei\nWird beim Aufheben gebunden\nEinzigartig\nHandwerksmaterial\n\"Ein sehr großes Monokel, das vor das sehr große Auge eines Konstrukts passen könnte.\"\nVerkaufspreis:" }
entries[183826] = { ["name"] = "Großer Schlapphut", ["text"] = "Monstrositätenflickerei\nWird beim Aufheben gebunden\nEinzigartig\nHandwerksmaterial\n\"Ein Hut, der aus der Mode gekommen ist und dort versteckt wurde, wo ihn niemand sieht.\"\nVerkaufspreis:" }
entries[183827] = { ["name"] = "Schwarzstahlrückenplatte", ["text"] = "Monstrositätenflickerei\nWird beim Aufheben gebunden\nEinzigartig\nHandwerksmaterial\n\"Traditionelle Rüstung der Soldaten des Schwarzhundaußenpostens.\"\nVerkaufspreis:" }
entries[183828] = { ["name"] = "Freundliche Krabbeltiere", ["text"] = "Monstrositätenflickerei\nWird beim Aufheben gebunden\nEinzigartig\nHandwerksmaterial\n\"Friedliche Käfer, die Bäume lieben.\"\nVerkaufspreis:" }
entries[183829] = { ["name"] = "Schleimkatze", ["text"] = "Monstrositätenflickerei\nWird beim Aufheben gebunden\nEinzigartig\nHandwerksmaterial\n\"Die Art von schrecklicher Kreatur, die ein Konstrukt zum Freund haben könnte.\"\nVerkaufspreis:" }
entries[183830] = { ["name"] = "Flaggenbausatz", ["text"] = "Monstrositätenflickerei\nWird beim Aufheben gebunden\nEinzigartig\nHandwerksmaterial\n\"Teile, aus denen eine Schlachtflagge für ein Konstrukt gebaut werden kann.\"\nVerkaufspreis:" }
entries[183831] = { ["name"] = "Bausatz für sicheres Fallen", ["text"] = "Monstrositätenflickerei\nWird beim Aufheben gebunden\nEinzigartig\nHandwerksmaterial\n\"Völlig unklar, wie das hierhergelangt ist, aber es könnte nützlich sein!\"\nVerkaufspreis:" }
entries[183832] = { ["name"] = "Geborgene Vorräte", ["text"] = "Questgegenstand\n\"Leicht beschädigt, aber der Inhalt ist intakt.\"" }
entries[183833] = { ["name"] = "Kashs Plunderbeutel", ["text"] = "Monstrositätenflickerei\nWird beim Aufheben gebunden\nEinzigartig\nHandwerksmaterial\n\"Ein großer Beutel voller Plunder, der von Sammler Kash sehr geschätzt wird.\"\nVerkaufspreis:" }
entries[183834] = { ["name"] = "Kiste mit Archäologiefragmenten der Drust", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Archäologie (1)\n\"Eine kleine Kiste mit Archäologiefragmenten der Drust.\"\n<Zum Öffnen rechtsklicken>" }
entries[183835] = { ["name"] = "Kiste mit Archäologiefragmenten der Zandalari", ["text"] = "Wird beim Aufheben gebunden\nBenötigt Archäologie (1)\n\"Eine kleine Kiste mit Archäologiefragmenten der Zandalari.\"\n<Zum Öffnen rechtsklicken>" }
entries[183836] = { ["name"] = "Schimmerschlick", ["text"] = "Questgegenstand\n\"Glitzert hell, während er Euch durch die Finger rinnt.\"" }
entries[183837] = { ["name"] = "Königlicher Torf", ["text"] = "Questgegenstand\n\"Ihr spürt, wie das Leben aus dieser Erde brechen will.\"" }
entries[183839] = { ["name"] = "Muster: Schwerer Grambalg", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen schweren Grambalg herstellt.\nBenötigt Lederverarbeitung der Schattenlande (80)\nBenötigt Hof der Ernter\n- Respektvoll\nVerkaufspreis:\nSchwerer Hornbalg\nHandwerksmaterial\n\"Wird von Spielercharakteren gesammelt, die den Beruf Kürschnerei ausüben.\"\nVerkaufspreis:\nBenötigt Hornbalg (10)" }
entries[183840] = { ["name"] = "Schwarzdornlehm", ["text"] = "Questgegenstand\n\"Hart und bröckelig\"" }
entries[183841] = { ["name"] = "Notleuchtfeuer", ["text"] = "Eiskrone\nWird beim Aufheben gebunden\nEinzigartig\nVerschießt ein Leuchtfeuer auf einen elenden Beobachter und fügt ihm 15 Feuerschaden zu.\n\"Sollte für die besten Ergebnisse zum angemessenen Zeitpunkt benutzt werden.\"" }
entries[183842] = { ["name"] = "Sündenmährenponyzügel", ["text"] = "Wird beim Aufheben gebunden\nErfordert einen respektvollen Ruf beim Gluthof.\n\"Schenkt diesen Gegenstand Eurem Gräberbutler, damit er das Reiten lernen und auf langen Reisen mit Euch mithalten kann.\"\nVerkaufspreis:" }
entries[183843] = { ["name"] = "Jungfleddermausharnisch", ["text"] = "Wird beim Aufheben gebunden\nErfordert einen ehrfürchtigen Ruf beim Gluthof.\n\"Schenkt diesen Gegenstand Eurem Gräberbutler, damit er lernen kann, wie man ein fliegendes Reittier lenkt, um Euch folgen zu können, wenn Ihr Euch in die Lüfte schwingt.\"\nVerkaufspreis:" }
entries[183844] = { ["name"] = "Ein Vorstellungsschreiben, die Knochenschmiedin", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Mograine vergeudet in seinem prägnant formulierten Vorstellungsschreiben für Knochenschmiedin Heirmir keine Zeit mit blumigen Formulierungen.\"" }
entries[183845] = { ["name"] = "Ein kurzer Brief an Schmiedin Sophone", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Der Polemarch berichtet Schmiedin Sophone ohne Umschweife von Euren Verdiensten und Eurer Ehrenhaftigkeit.\"" }
entries[183846] = { ["name"] = "Befehle an Gormschmied Cavina", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Jagdhauptmann Korayn hat eine Depesche verfasst, die Ihr dem Gormschmied Cavina bringen sollt, damit er Eure Sache unterstützt.\"" }
entries[183847] = { ["name"] = "Akolythenverkleidung", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Verkleidet Euch als Akolyth des Hauses der Rituale. Die Abklingzeit ist verringert, wenn die Verkleidung in Maldraxxus angewendet wird.\n\nKann nur von denjenigen verwendet werden, die den Nekrolords die Treue geschworen haben. (1 Stunde Abklingzeit)\nVerkaufspreis:" }
entries[183848] = { ["name"] = "Hastig geschriebene Notiz für Schmiedi", ["text"] = "Wird beim Aufheben gebunden\nDieser Gegenstand startet eine Quest.\n\"Rendel findet, Ihr solltet seinen Freund Schmiedi kennenlernen. Also hat er diese kurze Notiz verfasst.\"" }
entries[183849] = { ["name"] = "Seelensieberwurzeln", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 Intelligenz\nAnlegen: Eure Heilfähigkeiten haben eine Chance, Euer Ziel um 133 Gesundheit zu heilen. Wenn Eurem Ziel mehr Gesundheit fehlt als Euch, opfert Ihr bis zu 27 Gesundheit und heilt Euren Verbündeten um diesen Wert.\nVerkaufspreis:" }
entries[183850] = { ["name"] = "Wedel des Erweckers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Erhöht Euer Tempo 12 Sek. lang um 85 . (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[183851] = { ["name"] = "Dörrhainsteinling", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+7 [Beweglichkeit oder Stärke oder Intelligenz]\nAnlegen: Eure Schadensfähigkeiten haben eine Chance, zusätzlich 86 Schattenschaden zu verursachen.\nVerkaufspreis:" }
entries[183853] = { ["name"] = "Sündensturzkreischer", ["text"] = "Wird beim Aufheben gebunden\n80 ( 80)\n\"Lehrt Euch, wie man dieses Haustier beschwört.\"" }
entries[183854] = { ["name"] = "Flatterichs Anhänger", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Flatterich beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Der Gluthof\n- Respektvoll" }
entries[183855] = { ["name"] = "Steinis durchfluteter Rubin", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man Steini beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[183856] = { ["name"] = "Mystische Kugel der Meditation", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Findet Euren inneren Frieden, wo immer Ihr auch seid." }
entries[183857] = { ["name"] = "Stärke des Feuers", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDauer: 1 Stunde\nBenutzen: Bietet Schutz vor den verschiedenen eiskalten Gefahren des Reichs der Kälte.\n\"Wärmt die Seele.\"\nVerkaufspreis:" }
entries[183858] = { ["name"] = "Bauplan: Wurmlochgenerator: Schattenlande", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man einen Wurmlochgenerator: Schattenlande herstellt.\nBenötigt Ingenieurskunst der Schattenlande (70)\nBenötigt Die Unvergängliche Armee\n- Wohlwollend\nVerkaufspreis:\nWurmlochgenerator: Schattenlande\nWird bei Benutzung gebunden\nSpielzeug\nBenutzen: Öffnet ein Wurmloch, das es dem Benutzer ermöglicht, schnell an einen von mehreren Fixpunkten innerhalb der Schattenlande zu reisen. (15 Min Abklingzeit)\nBenötigt Ingenieurskunst der Schattenlande (1)\n\"VORSICHT: Ungenaue Befolgung der Sicherheitsrichtlinien kann Folgen haben, wie... Doppeltod? Turbotod? Lebendigkeit?\"\nVerkaufspreis:\nBenötigt Wurmdurchsetztes Getriebe (3), Zeitlich gesegnete Sprungfeder (7), Handvoll Laestritbolzen (20), Elethiumerz (3), Soleniumerz (10), Oxxeinerz (10), Phaedrumerz (10), Sinvyrerz (10)" }
entries[183859] = { ["name"] = "Dals Kurierabzeichen", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Das Steinscheusal lässt das Abzeichen fallen, als Ihr es freilasst. Damit könnt Ihr Dal in Zukunft beschwören.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)" }
entries[183860] = { ["name"] = "Der Todesmarsch: Eine Einführung in maldraxxische Etikette", ["text"] = "Wird beim Aufheben gebunden\n\"Gebt dieses Buch Eurem Gräberbutler, damit er sein Wissen über die richtigen Umgangsformen für Eure Gäste aus Maldraxxus auffrischen kann.\"" }
entries[183861] = { ["name"] = "Der Winterzyklus: Eine Sammlung der Etikette und Parabeln des Ardenwalds", ["text"] = "Wird beim Aufheben gebunden\n\"Gebt dieses Buch Eurem Gräberbutler, damit er sein Wissen über die richtigen Umgangsformen für Eure Gäste aus dem Ardenwald auffrischen kann.\"" }
entries[183862] = { ["name"] = "Die kultivierte Soiree: Detaillierte Einblicke in die Etikette der Venthyr, von Theotar", ["text"] = "Wird beim Aufheben gebunden\n\"Gebt dieses Buch Eurem Gräberbutler, damit er sein Wissen über die richtigen Umgangsformen für Eure Gäste aus Revendreth auffrischen kann.\"" }
entries[183863] = { ["name"] = "Auf dem richtigen Pfad: Etikette für den Umgang mit Aspiranten", ["text"] = "Wird beim Aufheben gebunden\n\"Gebt dieses Buch Eurem Gräberbutler, damit er sein Wissen über die richtigen Umgangsformen für Eure Gäste aus der Bastion auffrischen kann.\"" }
entries[183864] = { ["name"] = "Pläne: Mal des Handwerkers III", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein Mal des Handwerkers III herstellt.\nBenötigt Schmiedekunst der Schattenlande (80)\nVerkaufspreis:\nMal des Handwerkers III\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:\nBenötigt Laestriterz (20), Elethiumerz (3), Verdunkelter Stein (5), Leuchtender Fluxus (10)" }
entries[183865] = { ["name"] = "Technik: Mal des Handwerkers III", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein Mal des Handwerkers III herstellt.\nBenötigt Inschriftenkunde der Schattenlande (100)\nVerkaufspreis:" }
