entries[183867] = { ["name"] = "Bauplan: Mal des Handwerkers III", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein Mal des Handwerkers III herstellt.\nBenötigt Ingenieurskunst der Schattenlande (90)\nVerkaufspreis:\nMal des Handwerkers III\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:\nBenötigt Wurmdurchsetztes Getriebe (2), Zeitlich gesegnete Sprungfeder (2), Elethiumerz (3), Poröses Scheuermittel (10), Handvoll Laestritbolzen (15), Maschinenöl (10)" }
entries[183868] = { ["name"] = "Rezept: Mal des Handwerkers III", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein Mal des Handwerkers III herstellt.\nBenötigt Alchemie der Schattenlande\n(100)\nVerkaufspreis:\nMal des Handwerkers III\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:\nBenötigt Todesblüte (30), Nachtschatten (5), Runenverzierte Phiole , Destilliertes Todesextrakt (10)" }
entries[183869] = { ["name"] = "Muster: Mal des Handwerkers III", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein Mal des Handwerkers III herstellt.\nBenötigt Lederverarbeitung der Schattenlande (90)\nVerkaufspreis:\nMal des Handwerkers III\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:\nBenötigt Schweres Gramleder (3), Schwerer Hornbalg , Bleicher Knochen (25), Penumbrafaden (6), Gerbsalz (10)" }
entries[183870] = { ["name"] = "Muster: Mal des Handwerkers II", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nVe'nari muss Euch gegenüber herzlich oder positiver eingestellt sein.\n\"Lehrt Euch, wie man ein Mal des Handwerkers II herstellt.\"\nVerkaufspreis:" }
entries[183871] = { ["name"] = "Muster: Mal des Handwerkers III", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man ein Mal des Handwerkers III herstellt.\nBenötigt Schneiderei der Schattenlande (90)\nVerkaufspreis:\nMal des Handwerkers III\nWird beim Aufheben gebunden\nOptionales Handwerksmaterial\n\nBenutzbar mit: Muster aus Shadowlands für seltene (blaue) Rüstung und Zubehör.\nVerkaufspreis:\nBenötigt Lichtlose Seide (25), Schleierstoff (100), Penumbrafaden (10)" }
