entries[183876] = { ["name"] = "Federkiel der Korrespondenz", ["text"] = "Wird beim Aufheben gebunden\nSpielzeug\nBenutzen: Schickt einen Brief an einen Eurer besten Freunde vom Gluthof. Ihr erhaltet innerhalb eines Tages eine Antwort per Post. (1 Tag Abklingzeit)\nBenötigt den Ruf Bester Freund bei mindestens einem der Gäste des Gluthofs." }
entries[183877] = { ["name"] = "Eine mäandernde Geschichte", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Ein dicker Schmöker, der aber nicht wirklich mitreißt.\"" }
