entries[183879] = { ["name"] = "Ein eskapistischer Roman", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Er, äh, scheint dem Eskapismus gefrönt zu haben.\"" }
entries[183880] = { ["name"] = "Ein Reisetagebuch", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nDieser Gegenstand startet eine Quest.\n\"Diese Buch scheint gut rumgekommen zu sein.\"" }
