entries[184014] = { ["name"] = "Boshafte Kriegsspinne", ["text"] = "Wird beim Aufheben gebunden\nReittier\n(Accountweit)\nBenutzen: Lehrt Euch, wie man dieses Reittier beschwört.\nBeschwört dieses Reittier oder gibt es wieder frei.\n80 ( 80)\nBenötigt Unerfahrenes Reiten\nVerkaufspreis:\n\"Wenn ein mutiges Mitglied der Allianz zu sein nicht ausreicht, um das Herz Eures Gegners mit Angst zu erfüllen, fügt einfach eine Riesenspinne hinzu.\"\nPvP:\nShadowlands: Saison 1\nSaisonbelohnung für gewertete Arena und gewertete Schlachtfelder" }
entries[184015] = { ["name"] = "Gestohlenes Andenken", ["text"] = "Questgegenstand\n\"Ein verlorenes Andenken, das nach dem Tod des Hains zurückgelassen wurde.\"" }
entries[184016] = { ["name"] = "Schleicherflügel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke]\nBenutzen: Werdet 10 Sek. lang zum lauernden Raubtier, was Eure Geschwindigkeit um 69 erhöht. Ihr stürzt Euch außerdem auf den nächsten Gegner, der sich auf 8 Meter nähert, was ihm 3874 körperlichen Schaden zufügt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[184017] = { ["name"] = "Bargasts Leine", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke]\nBenutzen: Geht für 30 Sek. ein Band des Jägersmanns mit dem anvisierten Verbündeten ein. 25% des von Euch erlittenen Schadens werden auf diesen Verbündeten umgeleitet, bis zu insgesamt [ 11389 * (1 + Vielseitigkeit)] Schaden. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[184018] = { ["name"] = "Zersplittertes Herz von Al'ar", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke]\nAnlegen: Absorbiert bis zu 10234 Schaden eines sonst tödlichen Angriffs. Wenn dieser Effekt auftritt, brecht Ihr in Flammen aus, fügt Verbündeten und Gegnern in der Nähe [ 2433 * (1 + Vielseitigkeit)] Feuerschaden zu und stellt [ 7025 * (1 + Vielseitigkeit)] Gesundheit wieder her.\n\nDieser Effekt kann nur einmal alle 8 Min. auftreten.\nVerkaufspreis:" }
entries[184019] = { ["name"] = "Seelenzünder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 Intelligenz\nBenutzen: Aktiviert den Seelenzünder und opfert bis zu 2157 Gesundheit im Verlauf von 15 Sek., um 'Lodernde Woge' zu ermächtigen.\n\nAktiviert ihn erneut, um 'Lodernde Woge' einzusetzen, was Gegnern in einem kegelförmigen Bereich von 40 Metern [ 1541 * (1 + Vielseitigkeit)] Feuerschaden zufügt, die gleichmäßig aufgeteilt werden, und abhängig davon, wie lang der Seelenzünder aktiv war, ihnen zusätzlich bis zu 40% Schaden zufügt.\n\nDer Schaden erhöht sich pro getroffenem Gegner, bis zu 5 Gegnern. (1 Min. Abklingzeit)\nVerkaufspreis:" }
entries[184020] = { ["name"] = "Büschel schwelendes Gefieder", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 Intelligenz\nBenutzen: Stärkt Euren Verbündeten mit einem Büschel Phönixfedern, das ihn nach 6 Sek. um [ 5199 * (1 + Vielseitigkeit)] Gesundheit heilt. Dieser Wert erhöht sich abhängig von der fehlenden Gesundheit des Ziels um bis zu 25%. Wenn Euer Verbündeter tödlichen Schaden erleidet, wird dieser Effekt sofort ausgelöst. (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[184021] = { ["name"] = "Glyphe der Assimilierung", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 Intelligenz\nBenutzen: Fügt einem Gegner im Verlauf von 10 Sek. 1786 Arkanschaden zu.\n\nWenn Euer Ziel stirbt, während es mit 'Glyphe der Assimilierung' belegt ist, wird Eure Meisterschaft für das 2-Fache der verbleibenden Dauer der Glyphe um 160 erhöht. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[184022] = { ["name"] = "Zehrende Infusion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 Intelligenz\nAnlegen: Wenn Ihr einen Schadenszauber einsetzt, gewährt Eure nächste Einzelzielheilung für 30 Sek. 138 Lebensraub. Dieser Effekt kann nur einmal alle 10 Sek. auftreten.\nVerkaufspreis:" }
entries[184023] = { ["name"] = "Gefräßiger Stachel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 Stärke\nAnlegen: Eure Schadensfähigkeiten haben eine hohe Chance, 116 körperlichen Schaden zu verursachen und Euch um 300% des verursachten Schadens zu heilen. Bei überschüssiger Heilung dieses Effekts fügt Ihr Gegnern in der Nähe im Verlauf von 15 Sek. [ 98 * 5 * (1 + Vielseitigkeit)] körperlichen Schaden zu, der auf die Gegner aufgeteilt wird. Dies unterdrückt jedoch den Lebensdiebstahleffekt.\n\nDer Schaden erhöht sich pro getroffenem Gegner, bis zu 5 Gegnern.\nVerkaufspreis:" }
entries[184024] = { ["name"] = "Makabres Notenblatt", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Vier Tanzpartner erscheinen in einer zufälligen Aufstellung um Euch herum. Jeder von ihnen gewährt Euch stapelbar 20 Sek. lang 40 Tempo und 23 Geschwindigkeit, wenn Ihr Euch zu ihm hinbewegt. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
entries[184025] = { ["name"] = "Erinnerung an vergangene Sünden", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 [Beweglichkeit oder Stärke]\nBenutzen: Eure nächsten 5 Schaden verursachenden Fähigkeiten rufen 'Kollabierte Psyche' hervor, was 651 Schattenschaden verursacht und den durch 'Kollabierte Psyche' erlittenen Schaden des Ziels für 5 Sek. um 1% erhöht. Bis zu 25-mal stapelbar. (1.5s Abklingzeit) (2 Min Abklingzeit)\nVerkaufspreis:" }
entries[184026] = { ["name"] = "Hasserfüllte Kette", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+28 Beweglichkeit\nAnlegen: Wenn Eure prozentuale Gesundheit höher ist als die Eures Ziels, haben Eure Fähigkeiten eine sehr hohe Chance, [ 181 * (1 + Vielseitigkeit)] körperlichen Schaden zu verursachen.\n\nWenn Eure prozentuale Gesundheit niedriger ist als die Eures Ziels, haben Eure Fähigkeiten eine sehr hohe Chance, Euch um [ 247 * (1 + Vielseitigkeit)] Gesundheit zu heilen.\nVerkaufspreis:" }
entries[184027] = { ["name"] = "Wappenbuch der Steinlegion", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+31 [Beweglichkeit oder Stärke]\nAnlegen: Verkündet Eure Treue zur Steinlegion, was Eure Vielseitigkeit um 43 erhöht. Dieser Wert erhöht sich pro Steinlegionär in Eurer Gruppe um 5%.\nVerkaufspreis:" }
entries[184028] = { ["name"] = "Gesangbuch des Kabalisten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+31 Intelligenz\nAnlegen: Tretet dem blutroten Chor bei. Jede Minute schwillt Euer kritischer Trefferwert im Verlauf von 30 Sek. um ( 43 * 3) an, bevor er auf den normalen Wert zurücksinkt. Dieser Effekt erhöht sich pro Mitglied des blutroten Chors in Eurer Gruppe um 5%.\nVerkaufspreis:" }
entries[184029] = { ["name"] = "Managebundener Spiegel", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+31 Intelligenz\nAnlegen: Speichert pro 3240 verbrauchtem Mana [ 277 * (1 + Vielseitigkeit)] Heilung für 30 Sek. im Spiegel, bis zu [ 2307 * (1 + Vielseitigkeit)] Heilung.\nBenutzen: Heilt Euer Ziel um [ 1586 * (1 + Vielseitigkeit)] Gesundheit und zusätzlich um sämtliche im Spiegel gespeicherte Heilung. (1 Min Abklingzeit)\nVerkaufspreis:" }
entries[184030] = { ["name"] = "Schreckensfeuergefäß", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig anlegbar\nSchmuck\n+31 [Beweglichkeit oder Stärke oder Intelligenz]\nBenutzen: Entfesselt brennende Flammen auf Euer Ziel und fügt ihm 2787 Feuerschaden zu. (1 Min, 30 Sek. Abklingzeit)\nVerkaufspreis:" }
