entries[184219] = { ["name"] = "Abhandlung zur Beschaffung von Sündensteinfragmenten", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Das Lesen des Texts gewährt Euch das nötige Wissen, um beim Durchsuchen von Leichen in Revendreth manchmal mehr Sündensteinfragmente zu finden.\nBenötigt Die Eingeschworenen\n- Respektvoll" }
entries[184220] = { ["name"] = "Enzyklopädie der Bergung von Sündensteinfragmenten", ["text"] = "Wird an Kriegsmeute gebunden\nBenutzen: Das Lesen des Texts gewährt Euch das nötige Wissen, um beim Durchsuchen von Leichen in Revendreth manchmal mehr Sündensteinfragmente zu finden.\nErfordert einen ehrfürchtigen Ruf bei den Eingeschworenen.\n\"Eine umfangreiche Ausgabe, ideal für Studienanfänger.\"" }
entries[184221] = { ["name"] = "Federkiel des Archivars", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Lehrt Euch, wie man dieses Haustier beschwört.\nMit Rechtsklick diesen Begleiter beschwören oder wieder freigeben.\n80 ( 80)\nBenötigt Die Eingeschworenen\n- Ehrfürchtig" }
entries[184222] = { ["name"] = "Lemets Requisitionsbefehle", ["text"] = "Wird beim Aufheben gebunden\nBenutzen: Requiriert ein Steinscheusal, das jede Woche Sündensteinfragmente für Euch sammelt, die in einer Truhe in der Nähe von Archivar Fane deponiert werden.\nBenötigt Die Eingeschworenen\n- Wohlwollend" }
entries[184223] = { ["name"] = "Helm der Beherrschten", ["text"] = "Wird beim Aufheben gebunden\nEinzigartig\nSpielzeug\nBenutzen: Setzt den Helm auf, sodass Ihr Euch als einer der Schlundgebundenen ausgeben könnt. (1 Stunde Abklingzeit)\n\"Der Helm der Schlundgebundenen, immer noch von der beherrschenden Energie des Kerkermeisters durchdrungen.\"\nVerkaufspreis:" }
entries[184224] = { ["name"] = "Todschicklingsamen", ["text"] = "Monstrositätenflickerei\nWird beim Aufheben gebunden\nEinzigartig\nHandwerksmaterial\n\"Mit ein bisschen Hilfe sollten Pilze wachsen!\"\nVerkaufspreis:" }
entries[184225] = { ["name"] = "Kleines bewegliches Skelett", ["text"] = "Monstrositätenflickerei\nWird beim Aufheben gebunden\nEinzigartig\nHandwerksmaterial\n\"Ein merkwürdiger Gegenstand, verkauft von sehr merkwürdigen Verkäufern.\"\nVerkaufspreis:" }
