entries[184228] = { ["name"] = "Elektrisierter Seelenrückstand", ["text"] = "Questgegenstand\nEinzigartig\n\"Was auch immer das war, es wurde Opfer eines heftigen elektrischen Angriffs. In den Kaltherzinterstitia gefunden. Bolvar könnte sich dafür interessieren.\"" }
entries[184229] = { ["name"] = "Schattenhafter Schlüssel", ["text"] = "Questgegenstand\nEinzigartig\n\"Ein ungewöhnlich großer Schlüssel. In Mort'regar gefunden. Bolvar könnte sich dafür interessieren.\"" }
