entries[184309] = { ["name"] = "Notizen eines Venthyrinquisitors", ["text"] = "\"Todt kann sich der seltsamsten Sünden rühmen, mit denen ich es jemals zu tun hatte. Ich weiß wirklich nicht, welche Form der Sühne hier angemessen wäre.\"\nVerkaufspreis:" }
entries[184310] = { ["name"] = "Todts Sündenstein", ["text"] = "\"Stellt Euch die dümmstmöglichen, doch seltsam diabolischen und trotzdem extrem fehlgeleiteten Taten vor.\"\nVerkaufspreis:" }
